def update_mutation_state(ctx, nb, action, state):
    query = action.get("query", "")
    query_upper = query.upper()
    is_mutation = query_upper.startswith("UPDATE") or query_upper.startswith("INSERT") or query_upper.startswith("DELETE")
    if is_mutation:
        nb["mutation_attempted"] = True
        if not state.get("last_result_was_error"):
            nb["mutation_needs_verification"] = True
            nb["mutation_verified"] = False
        else:
            nb["mutation_needs_verification"] = False

def update_schema_state(ctx, nb, predicates):
    if predicates.get("unknown_column_error") or predicates.get("syntax_error"):
        nb["need_schema_probe"] = True
        nb["fixing_unknown_column"] = True
    if predicates.get("last_result_error"):
        nb["last_error_was_quoting"] = True

def hook(ctx, nb):
    action = ctx.get("action", {})
    state = ctx.get("state", {})
    predicates = ctx.get("predicates", {})
    update_schema_state(ctx, nb, predicates)
    if action.get("tool") == "execute_sql":
        update_mutation_state(ctx, nb, action, state)
    if action.get("tool") == "execute_sql" and nb.get("mutation_needs_verification"):
        if not state.get("last_result_was_error"):
            nb["mutation_verified"] = True
            nb["mutation_needs_verification"] = False
    return None

def hook(ctx, nb):
    action = ctx.get("action", {})
    predicates = ctx.get("predicates", {})
    task = ctx.get("task", {})
    last_hint = nb.get("last_hint", "")
    if predicates.get("unknown_column_error") or predicates.get("syntax_error"):
        hint_msg = "Schema error detected. Use SHOW TABLES to list tables, then DESCRIBE `table_name` to see exact column names. Use backticks for names with spaces or special characters."
        if hint_msg != last_hint:
            nb["last_hint"] = hint_msg
            return {"message": hint_msg}
    if action.get("tool") == "commit_final_answer":
        is_mutation_task = task.get("task_type", "") in ["update", "insert", "delete"] or predicates.get("mutation_task")
        if is_mutation_task and nb.get("mutation_attempted") and not nb.get("mutation_verified"):
            hint_msg = "Verify mutation succeeded with a SELECT query before committing. Check that the data was actually updated or inserted."
            if hint_msg != last_hint:
                nb["last_hint"] = hint_msg
                return {"message": hint_msg}
    if nb.get("need_schema_probe") and action.get("tool") == "execute_sql":
        query = action.get("query", "")
        query_upper = query.upper()
        if "DESCRIBE" not in query_upper and "SHOW" not in query_upper:
            hint_msg = "Consider probing schema first with DESCRIBE `table_name` to verify exact column names before writing queries."
            if hint_msg != last_hint:
                nb["last_hint"] = hint_msg
                return {"message": hint_msg}
    return None
